/**
 * Golden contract for the SM-18 format-read port follow-up on
 * `info/contents.dat` (sm18-re gitlab #39).
 *
 * Follow-up to #36. v1 landed `parseElementInfo` + `parseCompon`; this gate
 * adds `parseContents`. The `format_read` surface in
 * `sm18-re:docs/port-surface.json` only flips when every follow-up has
 * landed; a green run here is proof of this group's landing, not of the whole
 * surface.
 *
 * The fixture `test/fixtures/sm18-port-format-read-contents.json` is a mirror
 * of `sm18-re:tests/fixtures/port-format-read-contents.json`, regenerated by
 * `sm18-re:scripts/export-port-format-read-contents-fixture.py` on the sample
 * collection "ABC of SuperMemo 18". The lane re-copies the mirror on every
 * fixture change so sm18-re's gate catches drift on either side.
 *
 * This file is brief-writer owned. The lane adds
 *
 *   parseContents(bytes: Uint8Array): ContentsRecord[]
 *
 * to `src/sm18-format-read.ts` additively — the v1 parsers must remain
 * exported and `test/sm18-port-format-read.test.ts` must stay green.
 *
 * Record shape: a `_raw`-dropped projection of `smfmt.contents.parse`. The
 * ten values are keyed as `unknown_0x%02x` (Python-reference offset labels).
 * Do NOT introduce semantic names (`parent` / `child` / `sibling`) in TS; the
 * reference deliberately refuses to name them until their tree roles are
 * defended, and the port inherits the non-naming. The fixture cannot catch a
 * mislabelled value.
 *
 * Error contract: a file whose length is not a multiple of 37 (`0x25`) is an
 * error, not a truncation to tolerate; the reference raises `ValueError` and
 * the port must throw.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const FIXTURE_PATH = join(
  __dirname,
  "fixtures",
  "sm18-port-format-read-contents.json",
);
const MODULE_SPEC = ["..", "src", "sm18-format-read.ts"].join("/");

interface ContentsRecord {
  unknown_0x00: number;
  unknown_0x01: number;
  unknown_0x05: number;
  unknown_0x09: number;
  unknown_0x0d: number;
  unknown_0x11: number;
  unknown_0x15: number;
  unknown_0x19: number;
  unknown_0x1d: number;
  unknown_0x21: number;
}

interface FixtureFile {
  path: string;
  byte_length: number;
  bytes_b64: string;
  record_count: number;
  records: ContentsRecord[];
}

interface Fixture {
  schema: number;
  collection: string;
  scope: string[];
  files: FixtureFile[];
}

interface PortModule {
  parseContents: (bytes: Uint8Array) => ContentsRecord[];
}

async function loadPort(): Promise<PortModule | null> {
  try {
    const mod = await import(MODULE_SPEC);
    if (typeof mod?.parseContents !== "function") {
      return null;
    }
    return mod as PortModule;
  } catch {
    return null;
  }
}

function decodeBase64(encoded: string): Uint8Array {
  return new Uint8Array(Buffer.from(encoded, "base64"));
}

const fixture: Fixture = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));

test("fixture declares the contents scope and non-empty file", () => {
  assert.equal(fixture.schema, 1);
  assert.deepEqual(fixture.scope, ["contents"]);
  assert.equal(fixture.files.length, 1);
  const file = fixture.files[0];
  assert.equal(file.path, "info/contents.dat");
  assert.ok(file.record_count > 0);
  assert.ok(file.byte_length > 0);
  assert.equal(file.byte_length % 37, 0, "byte length must be a multiple of 37");
  assert.equal(file.record_count * 37, file.byte_length);
});

test("src/sm18-format-read.ts exports parseContents", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("parseContents not implemented yet");
    return;
  }
  assert.equal(typeof port.parseContents, "function");
});

for (const file of fixture.files) {
  test(`format-read-contents: ${file.path} parses to ${file.record_count} records`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("parseContents not implemented yet");
      return;
    }
    const bytes = decodeBase64(file.bytes_b64);
    assert.equal(
      bytes.byteLength,
      file.byte_length,
      `byte count for ${file.path}`,
    );
    const parsed = port.parseContents(bytes);
    assert.equal(
      parsed.length,
      file.record_count,
      `record count for ${file.path}`,
    );
    for (let i = 0; i < file.record_count; i += 1) {
      assert.deepEqual(
        parsed[i],
        file.records[i],
        `record ${i} of ${file.path} must match the fixture projection`,
      );
    }
  });

  test(`format-read-contents: ${file.path} throws on partial trailing record`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("parseContents not implemented yet");
      return;
    }
    const bytes = decodeBase64(file.bytes_b64);
    const truncated = bytes.slice(0, bytes.byteLength - 1);
    assert.throws(
      () => port.parseContents(truncated),
      "length not a multiple of 37 must throw",
    );
  });
}
